#include <iostream>
#include <string>
#include <vector>

struct Time {
    int hours;
    int minutes;
    int seconds;
};

Time split_time(int total) {
    return Time{total / 3600, total / 60 % 60, total % 60};
}

struct Job {
    std::string bike;
    double price;
};

int main() {
    auto [h, m, s] = split_time(3725);
    std::cout << h << "h " << m << "m " << s << "s\n";

    std::vector<Job> jobs{{"Racer", 45.5}, {"Trike", 30.25}};
    for (const auto& [bike, price] : jobs) {
        std::cout << bike << " costs $" << price << '\n';
    }
}

