#include <iostream>
#include <vector>

struct MinMax {
    int lo;
    int hi;
};

MinMax min_max(const std::vector<int>& v) {
    MinMax r{v[0], v[0]};
    for (int x : v) {
        if (x < r.lo) r.lo = x;
        if (x > r.hi) r.hi = x;
    }
    return r;
}

int main() {
    std::vector<int> temps{14, 9, 21, 17, 11};
    MinMax m = min_max(temps);
    std::cout << "Coldest " << m.lo << ", warmest " << m.hi << '\n';
}

